#!/usr/bin/env bash
# Concatenate the pipeline SQL into one file to paste/run in the Databricks SQL editor:
#   databricks/sql/ux_pipeline_all.sql = 00 setup, 01 bronze DDL, 01b load, 02 silver, 03 gold, 06 chat silver,
#   07 chat gold, 05 comments (last, so it can comment on every table)
# with ${catalog}/${schema}/${volume} filled in. Every step is safe to re-run.
# Also writes databricks/sql/ux_ai_labels.sql from 04 (AI Functions: calls a model per prompt, so it is run separately)
# and databricks/sql/ux_ai_designer.sql from 08 (ai_gen drafts design proposals; 08 itself is generated by
# databricks/designer/propose.py sql).
# Usage: scripts/build-pipeline-sql.sh [--check]    (env CATALOG, SCHEMA, VOLUME override the defaults)
set -euo pipefail
cd "$(dirname "$0")/.."
CATALOG=${CATALOG:-workspace} SCHEMA=${SCHEMA:-ux_telemetry} VOLUME=${VOLUME:-raw_events}
OUT=databricks/sql/ux_pipeline_all.sql
AI_OUT=databricks/sql/ux_ai_labels.sql
DESIGN_OUT=databricks/sql/ux_ai_designer.sql
subst() { sed -e "s/\${catalog}/${CATALOG}/g" -e "s/\${schema}/${SCHEMA}/g" -e "s/\${volume}/${VOLUME}/g" "$1"; }
gen_ai() {
  echo "-- GENERATED by scripts/build-pipeline-sql.sh from databricks/sql/04_ai_prompt_intent.sql. Do not edit by hand."
  echo "-- Run after ux_pipeline_all.sql. Target: ${CATALOG}.${SCHEMA}."
  subst databricks/sql/04_ai_prompt_intent.sql
}
gen_design() {
  echo "-- GENERATED by scripts/build-pipeline-sql.sh from databricks/sql/08_ai_design_proposals.sql. Do not edit by hand."
  echo "-- Run after ux_pipeline_all.sql. Target: ${CATALOG}.${SCHEMA}."
  subst databricks/sql/08_ai_design_proposals.sql
}
gen() {
  echo "-- GENERATED by scripts/build-pipeline-sql.sh from databricks/sql/{00,01,01b,02,03,06,07,05}*.sql. Do not edit by hand."
  echo "-- Target: ${CATALOG}.${SCHEMA}, Volume ${VOLUME}. Run all statements in order; every step is safe to re-run."
  for f in 00_setup 01_bronze_ddl 01b_bronze_load 02_silver 03_gold 06_silver_chat 07_gold_chat 05_comments; do
    printf '\n-- ===================================================================== %s.sql\n' "$f"
    subst "databricks/sql/$f.sql"
  done
}
if [[ "${1:-}" == "--check" ]]; then
  diff -q <(gen) "$OUT" >/dev/null || { echo "$OUT is stale: run scripts/build-pipeline-sql.sh"; exit 1; }
  diff -q <(gen_ai) "$AI_OUT" >/dev/null 2>&1 || { echo "$AI_OUT is stale: run scripts/build-pipeline-sql.sh"; exit 1; }
  diff -q <(gen_design) "$DESIGN_OUT" >/dev/null 2>&1 || { echo "$DESIGN_OUT is stale: run scripts/build-pipeline-sql.sh"; exit 1; }
  echo "$OUT, $AI_OUT and $DESIGN_OUT up to date"
else
  gen > "$OUT"; gen_ai > "$AI_OUT"; gen_design > "$DESIGN_OUT"; echo "wrote $OUT, $AI_OUT and $DESIGN_OUT"
fi
